"""Draft value qualification. Import is inert; main reads all four source sheets.

Do not execute on the real workbook before the root's value-access freeze.
The OOXML/hash/identity conventions match lineage_identity.py; that script is
not imported because it reads and writes files at import time. No source repair.
"""
from collections import Counter, defaultdict
import hashlib
import json
import math
from pathlib import Path
import posixpath
import re
import xml.etree.ElementTree as ET
import zipfile

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / 'data/external/core_completion_round_20261023/lineage/circadian2018_lineages.xlsx'
OUTPUT = ROOT / 'log/20261023/core_completion_round/task/LINEAGE_VALUES.json'
SHA256 = '212e5ca40af8fe5f1b07baf613459f275c7b97a2ec99e31fa2505af252a3f130'
SHAPE = (394, 243)
SHEETS = ('Lineage', 'p53', 'Divisions', 'Apoptosis')
NS = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
REL = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'


def load_arrays(source=SOURCE, sheet_names=SHEETS):
    """Return {sheet: row-major list[list[float]]}; only requested sheets open.

    Blanks are NaN (not zero). Reject formulas, nonnumeric cells, duplicate cell
    refs, unexpected dimensions and changed bytes without guessing corrections.
    Ordinary finite/out-of-domain values remain unchanged for qualify_arrays.
    A caller may request only ('Lineage',) for permitted identity diagnostics.
    """
    source = Path(source)
    if hashlib.sha256(source.read_bytes()).hexdigest() != SHA256:
        raise ValueError('Source SHA256 differs from qualified source')
    if not set(sheet_names).issubset(SHEETS):
        raise ValueError('Unregistered sheet requested')
    arrays = {}
    with zipfile.ZipFile(source) as z:
        workbook = ET.fromstring(z.read('xl/workbook.xml'))
        relations = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        targets = {r.attrib['Id']: r.attrib['Target'] for r in relations}
        sheets = {s.attrib['name']: s.attrib[REL]
                  for s in workbook.findall('.//s:sheet', NS)}
        for name in sheet_names:
            member = posixpath.normpath(posixpath.join('xl', targets[sheets[name]]))
            if not re.fullmatch(r'xl/worksheets/sheet[1-4]\.xml', member):
                raise ValueError('Unexpected worksheet relationship')
            tree = ET.fromstring(z.read(member))
            if tree.find('s:dimension', NS).attrib['ref'] != 'A1:II394':
                raise ValueError(f'Unexpected dimensions: {name}')
            array = [[math.nan] * SHAPE[1] for _ in range(SHAPE[0])]
            seen = set()
            for cell in tree.findall('.//s:sheetData/s:row/s:c', NS):
                ref = cell.attrib['r']
                if ref in seen or cell.find('s:f', NS) is not None:
                    raise ValueError(f'Duplicate cell or formula: {name}!{ref}')
                seen.add(ref)
                if cell.attrib.get('t', 'n') != 'n':
                    raise ValueError(f'Nonnumeric cell type: {name}!{ref}')
                match = re.fullmatch(r'([A-Z]+)([0-9]+)', ref)
                if match is None:
                    raise ValueError(f'Invalid cell reference: {name}!{ref}')
                col = 0
                for char in match.group(1):
                    col = col * 26 + ord(char) - 64
                row = int(match.group(2))
                if not (1 <= row <= SHAPE[0] and 1 <= col <= SHAPE[1]):
                    raise ValueError(f'Cell outside registered shape: {name}!{ref}')
                token = cell.findtext('s:v', default='', namespaces=NS)
                if token:
                    array[row - 1][col - 1] = float(token)
            arrays[name] = array
    return arrays


def qualify_arrays(arrays):
    """Summarize conflicts without choosing rows, fixing labels or deriving Y.

    Synthetic arrays may have any common rectangular size. Numeric conflicts
    retain source row/frame locations; at most eight examples per issue.
    """
    if set(arrays) != set(SHEETS):
        raise ValueError('Need all four registered arrays')
    rows = len(arrays['Lineage'])
    frames = len(arrays['Lineage'][0])
    if not all(len(a) == rows and all(len(r) == frames for r in a)
               for a in arrays.values()):
        raise ValueError('Array shapes disagree')
    counts, examples = Counter(), defaultdict(list)

    def flag(issue, row, frame, **details):
        counts[issue] += 1
        if len(examples[issue]) < 8:
            examples[issue].append({'row': row + 1, 'frame': frame + 1, **details})

    lineage, p53 = arrays['Lineage'], arrays['p53']
    division, death = arrays['Divisions'], arrays['Apoptosis']
    for row in range(rows):
        for frame in range(frames):
            identity = lineage[row][frame]
            if not math.isfinite(identity) or identity < 0 or identity != int(identity):
                flag('invalid_lineage_identity', row, frame)
            for name in ('Divisions', 'Apoptosis'):
                if arrays[name][row][frame] not in (0, 1):
                    flag(name + '_nonbinary_or_missing', row, frame)
            value = p53[row][frame]
            if not math.isfinite(value):
                flag('p53_nonfinite_or_missing', row, frame)
            # Other negative fluorescence is reported, not judged impossible:
            # background subtraction can produce values below zero.
            elif value < 0 and value != -1:
                flag('p53_negative_other_than_missing_sentinel', row, frame)
            if identity > 0 and value == -1:
                flag('positive_identity_but_p53_missing', row, frame)
            if identity == 0 and math.isfinite(value) and value != -1:
                flag('zero_identity_but_p53_observed', row, frame)
            if division[row][frame] == death[row][frame] == 1:
                flag('simultaneous_division_and_apoptosis', row, frame)
            if identity == 0 and (division[row][frame] == 1 or death[row][frame] == 1):
                flag('event_on_zero_identity_frame', row, frame)

    duplicate_groups = 0
    for frame in range(frames):
        owners = defaultdict(list)
        for row in range(rows):
            identity = lineage[row][frame]
            if math.isfinite(identity) and identity > 0 and identity == int(identity):
                owners[int(identity)].append(row)
        for identity, group in owners.items():
            if len(group) < 2:
                continue
            duplicate_groups += 1
            for name in ('p53', 'Divisions', 'Apoptosis'):
                values = [arrays[name][r][frame] for r in group]
                if not all(math.isfinite(v) for v in values) or len(set(values)) != 1:
                    flag(name + '_same_frame_identity_conflict', group[0], frame,
                         identity=identity, rows=[r + 1 for r in group])

    transition_alignment = Counter()
    for row in range(rows):
        for frame in range(1, frames):
            old, new = lineage[row][frame - 1:frame + 1]
            if not (math.isfinite(old) and math.isfinite(new)):
                continue
            if old > 0 and new > 0 and old != new:
                previous = division[row][frame - 1] == 1
                current = division[row][frame] == 1
                key = ('both' if previous and current else 'previous_frame' if previous
                       else 'current_frame' if current else 'neither_frame')
                transition_alignment[key] += 1
                if key == 'neither_frame':
                    flag('identity_change_without_adjacent_division', row, frame)
            # Same ID may persist in one daughter: not an error by itself.
            if division[row][frame] == 1 and old == new and new > 0:
                counts['division_with_unchanged_row_identity_allowed_by_dictionary'] += 1

    return {
        'status': 'DIAGNOSTIC_ONLY_REQUIRES_SEMANTIC_REVIEW',
        'shape': [rows, frames],
        'same_frame_duplicate_identity_groups_checked': duplicate_groups,
        'issue_counts': dict(sorted(counts.items())),
        'issue_examples': dict(sorted(examples.items())),
        'nonzero_identity_transition_division_alignment': dict(transition_alignment),
        'source_corrections_applied': 0,
        'endpoint_or_cohort_constructed': False,
        'notes': [
            'Counts may double-count shared mother paths; they are not biological event counts.',
            'p53=-1 and Lineage=0 are missing/untracked indicators, never automatic death labels.',
            'Adjacent-frame alignment is diagnosed in both directions, not silently shifted.',
            'Zero-identity events, conflicts and extra negative p53 need interpretation; no automatic repair.',
        ],
    }


def main():
    arrays = load_arrays()
    result = qualify_arrays(arrays)
    result['source_sha256'] = SHA256
    result['opened_cell_sheets'] = list(SHEETS)
    OUTPUT.write_text(json.dumps(result, indent=2, allow_nan=False), encoding='utf-8')
    print(json.dumps(result, indent=2, allow_nan=False))


if __name__ == '__main__':
    main()

