"""Read workbook schema and text headers only, not numeric response cells."""
from pathlib import Path
import csv
import io
import json
import zipfile
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[2]
DATA = ROOT / "data/external/fpmtb_zenodo_7370747"
LOG = ROOT / "log/20261023/roadmap_feasibility"
NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"


def strings(z):
    if "xl/sharedStrings.xml" not in z.namelist():
        return []
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    return ["".join(x.itertext()) for x in root]


def worksheets(z):
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    targets = {x.attrib["Id"]: x.attrib["Target"] for x in rels}
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    for sheet in wb.find("m:sheets", NS):
        target = targets[sheet.attrib[f"{{{REL}}}id"]]
        yield sheet.attrib["name"], target.lstrip("/") if target.startswith("/") else "xl/" + target


def text_cell(cell, shared):
    if cell.attrib.get("t") == "s":
        return shared[int(cell.find("m:v", NS).text)]
    if cell.attrib.get("t") == "inlineStr":
        return "".join(cell.find("m:is", NS).itertext())
    return None


def main():
    result = []
    with zipfile.ZipFile(DATA / "Functional_Precision_Medicine_Tumor_Board_AML.zip") as package:
        for name in package.namelist():
            short = Path(name).name
            if not short.startswith(("File_0_", "File_2_", "File_3.", "File_4_", "File_9_")):
                continue
            raw = package.read(name)
            path = DATA / short
            if not path.exists():
                path.write_bytes(raw)
            if short.endswith(".csv"):
                header = next(csv.reader(io.StringIO(raw.decode("utf-8-sig"))))
                result.append({"file": short, "header": header})
                continue
            with zipfile.ZipFile(io.BytesIO(raw)) as z:
                shared = strings(z)
                for sheet, target in worksheets(z):
                    rows = []
                    dimension = None
                    with z.open(target) as stream:
                        for _, elem in ET.iterparse(stream, events=("end",)):
                            tag = elem.tag.rsplit("}", 1)[-1]
                            if tag == "dimension":
                                dimension = elem.attrib.get("ref")
                            if tag == "row":
                                if int(elem.attrib["r"]) > (12 if short.startswith("File_3.2") else 2):
                                    break
                                cells = {c.attrib["r"]: text_cell(c, shared) for c in elem}
                                rows.append({k: v for k, v in cells.items() if v is not None})
                                elem.clear()
                    result.append({"file": short, "sheet": sheet, "dimension": dimension,
                                   "first_two_rows_text_only": rows})
    (LOG / "SCHEMA.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
    for item in result:
        compact = dict(item)
        if "first_two_rows_text_only" in item:
            compact["first_two_rows_text_only"] = [dict(list(r.items())[:22]) for r in item["first_two_rows_text_only"]]
        print(json.dumps(compact))


if __name__ == "__main__":
    main()

"""Second identity extraction using whole-sheet parsing; no endpoint decoding."""
from pathlib import Path
import csv
import hashlib
import json
import re
import zipfile
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[2]
DATA = ROOT / 'data/external/fpmtb_zenodo_7370747'
LOG = ROOT / 'log/20261023/roadmap_feasibility'
NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

def rows(prefix, columns, first):
    path = next(DATA.glob(prefix + '*.xlsx'))
    with zipfile.ZipFile(path) as z:
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        texts = [''.join(e.itertext()) for e in ss]
        sheet = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
        result = []
        for row in sheet.findall('m:sheetData/m:row', NS):
            if int(row.attrib['r']) < first:
                continue
            record = {}
            for cell in row:
                col = re.sub('[0-9]', '', cell.attrib['r'])
                if col in columns and cell.attrib.get('t') == 's':
                    record[col] = texts[int(cell.find('m:v', NS).text)]
            result.append(record)
        return result

def main():
    expected = json.loads((LOG / 'MEMBERSHIP.json').read_text())
    common = {r['B']: r['A'] for r in rows('File_0_', {'A', 'B'}, 2)}
    with next(DATA.glob('File_9_*.csv')).open(encoding='utf-8-sig', newline='') as stream:
        rna = {r['Sample_ID'] for r in csv.DictReader(stream)}
    pairs = [(r['A'], r['B']) for r in rows('File_3.2_', {'A', 'B'}, 4)]
    sample_drugs = {}
    for sample, drug in pairs:
        sample_drugs.setdefault(sample, set()).add(drug)
    # Read every column from the first wide header.
    with zipfile.ZipFile(next(DATA.glob('File_3.1_*.xlsx'))) as z:
        ss = [''.join(e.itertext()) for e in ET.fromstring(z.read('xl/sharedStrings.xml'))]
        header = ET.fromstring(z.read('xl/worksheets/sheet1.xml')).find('m:sheetData/m:row', NS)
        wide = {ss[int(c.find('m:v', NS).text)] for c in header if c.attrib.get('t') == 's'} - {'Drug_ID', 'Drug_name'}
    assay = {r['B'] for r in rows('File_4_', {'B'}, 2) if r.get('B')}
    library = {r['A'] for r in rows('File_2_', {'A'}, 2)}
    response = set(sample_drugs)
    matched = response & rna & common.keys()
    disputed = (response ^ wide) | ((response & common.keys()) ^ assay)
    excluded_patients = {common[s] for s in disputed if s in common}
    strict = {s for s in matched & wide & assay if common[s] not in excluded_patients}
    actual = [len(pairs), len(set(pairs)), len(response), len(matched), len({common[s] for s in matched}), len(strict), len({common[s] for s in strict}), len(set.intersection(*(sample_drugs[s] & library for s in strict)))]
    want = [expected[k] for k in ['response_records', 'response_unique_pairs', 'response_samples', 'matched_rna_response_common_samples', 'matched_patient_groups']]
    want += [expected['conservative_identity_only_subset'][k] for k in ['samples', 'patient_groups', 'common_compound_record_ids']]
    assert actual == want, (actual, want)
    extracted = []
    with zipfile.ZipFile(DATA / 'Functional_Precision_Medicine_Tumor_Board_AML.zip') as archive:
        for path in DATA.iterdir():
            if path.suffix not in {'.csv', '.xlsx'}:
                continue
            member = next(n for n in archive.namelist() if Path(n).name == path.name)
            assert path.read_bytes() == archive.read(member), path.name
            extracted.append({'file': path.name, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest()})
    result = {'status': 'PASS', 'counts': actual, 'extracted_files_match_archive': extracted,
              'scope': 'Second parser by same agent; identity counts and file integrity only. No model, endpoint QC, author-truth or independent researcher verification.'}
    (LOG / 'VERIFICATION.json').write_text(json.dumps(result, indent=2), encoding='utf-8')
    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()

